// Obtenemos el array de IDs basándonos en tu referencia y la imagen
// Nota: Respeto el typo 'camapign_id' que aparece en tu estructura
const idList = $('When Executed by Another Workflow').first().json.camapign_id.propertyName;

// Iteramos sobre el array para devolver un item por cada ID
return idList.map(id => {
  return {
    json: {
      id: id
    }
  };
});

// ==========================================
// 1. OBTENCIÓN DE DATOS (INPUTS BLINDADOS)
// ==========================================

// A. Obtener el Presupuesto Mensual del Cliente
// Usamos try/catch o valores por defecto para evitar crash si falta la columna
let userMonthlyBudget = 0;
try {
    const colP = ($input.item.json.column_values || []).find(c => c.column && c.column.title === 'Presupuesto mensual');
    if (colP) { userMonthlyBudget = parseFloat(String(colP.text || "0").replace(/[^0-9.]/g, "") || "0"); }
} catch (e) {
    userMonthlyBudget = 0;
}

// B. Obtener la Data de la Campaña (Webhook/Trigger)
// Verificamos si el nodo existe antes de pedir .json
const triggerNode = $('When Executed by Another Workflow').first();
const rawPayload = triggerNode ? triggerNode.json : {};

// C. BÚSQUEDA DE CAMPAÑAS (A prueba de balas)
// Buscamos el array en las ubicaciones más probables.
// Si no encuentra nada, asigna un array vacío [] para que el bucle no explote.
let campaigns = [];

if (rawPayload.body && Array.isArray(rawPayload.body.campaigns)) {
    // Caso estándar según tu JSON
    campaigns = rawPayload.body.campaigns;
} else if (Array.isArray(rawPayload.campaigns)) {
    // Caso donde el body se aplanó
    campaigns = rawPayload.campaigns;
} else if (rawPayload.body && rawPayload.body.strategy && Array.isArray(rawPayload.body.strategy.campaigns)) {
    // Caso rebuscado (dentro de strategy)
    campaigns = rawPayload.body.strategy.campaigns;
}

// ==========================================
// 2. LÓGICA DE CÁLCULO (Motor Financiero)
// ==========================================

let totalDailyCents = 0;
let calculationLog = []; 

// El bucle ahora es seguro porque 'campaigns' siempre será un array (aunque esté vacío)
for (const campaign of campaigns) {
    let campaignCents = 0;
    let budgetType = "ABO"; 

    // Normalizar detección de CBO/GLOBAL
    const typeStr = (campaign.budgetType || "").toUpperCase();

    if (typeStr.includes("CBO") || typeStr.includes("GLOBAL")) {
        budgetType = "CBO";
        // En CBO tomamos el budget directo. Si no existe, 0.
        campaignCents = parseInt(campaign.budget || 0);
    } else {
        budgetType = "ABO";
        // En ABO sumamos los adsets. Validamos que adsets sea un array.
        if (Array.isArray(campaign.adsets)) {
            campaignCents = campaign.adsets.reduce((sum, adset) => {
                return sum + parseInt(adset.budget || 0);
            }, 0);
        }
    }

    // Acumular
    totalDailyCents += campaignCents;

    // Log
    calculationLog.push({
        campaign_name: campaign.name || "Sin Nombre",
        type: budgetType,
        cents: campaignCents,
        usd: (campaignCents / 100).toFixed(2)
    });
}

// ==========================================
// 3. PROYECCIONES Y COMPLIANCE
// ==========================================

const dailySpendUSD = totalDailyCents / 100;
const projectedMonthlySpend = dailySpendUSD * 30;

let percentageUsed = 0;
if (userMonthlyBudget > 0) {
    percentageUsed = (projectedMonthlySpend / userMonthlyBudget) * 100;
}

// Validación Binaria (8% - 12%)
let status = "FAIL";
// Nota: Si el gasto es 0 (porque no leyó campañas), fallará por estar debajo del 8%.
if (percentageUsed >= 8.00 && percentageUsed <= 12.00) {
    status = "PASS";
}

let analysisMessage = "";
if (status === "PASS") {
    analysisMessage = `Correcto: El gasto proyectado ($${projectedMonthlySpend.toFixed(2)}) es el ${percentageUsed.toFixed(2)}% del presupuesto ($${userMonthlyBudget}).`;
} else {
    analysisMessage = `Fallo de Presupuesto: El gasto proyectado ($${projectedMonthlySpend.toFixed(2)}) representa el ${percentageUsed.toFixed(2)}% del presupuesto declarado ($${userMonthlyBudget}). Está fuera del rango permitido (8%-12%).`;
}

// ==========================================
// 4. SALIDA FINAL
// ==========================================

return {
    json: {
        budget_audit: {
            status: status,
            metrics: {
                user_budget_limit: userMonthlyBudget,
                daily_spend_usd: dailySpendUSD,
                projected_monthly_spend: projectedMonthlySpend,
                percentage_used: parseFloat(percentageUsed.toFixed(2))
            },
            analysis: analysisMessage,
            breakdown_log: calculationLog,
            debug_info: {
                campaigns_found: campaigns.length // Para saber si encontró las campañas
            }
        }
    }
};

